parameters.functionCode:
// Parse webhook payload da Evolution API
const msg = $input.first().json.data;
const instanceName = msg.instanceName;
const message = msg.messages[0];

// Extrair informações
const leadPhone = message.key.remoteJid.replace('@c.us', '');
const leadText = message.message.conversation || '';
const leadName = message.pushName || 'Desconhecido';
const timestamp = new Date(message.messageTimestamp * 1000);

return {
  leadPhone,
  leadText,
  leadName,
  timestamp,
  instanceName,
  isFromMe: message.key.fromMe
};

// Extrair resposta da IA
const response = $input.first().json;

if (response.content && response.content[0]) {
  const iaResponse = response.content[0].text || '';

  return {
    iaResponse,
    usage: response.usage,
    success: true
  };
} else {
  return {
    iaResponse: 'Desculpe, ocorreu um erro. Pode tentar novamente?',
    error: true,
    success: false
  };
}

// Sistema de pontuação para qualificação de leads
const iaResponse = $input.first().json.iaResponse || '';
const leadText = $node[\"Parse Mensagem\"].json.leadText || '';
const fullText = (iaResponse + ' ' + leadText).toLowerCase();

let score = 0;

// 1. URGÊNCIA (máx 40 pontos)
if (fullText.match(/urgente|preciso|já|semana que vem|próximos dias|imediato|rush/)) score += 40;
else if (fullText.match(/mês que vem|próximas semanas|30 dias/)) score += 30;
else if (fullText.match(/próximos 3 meses|segundo trimestre|antes do verão|90 dias/)) score += 15;
else if (fullText.match(/final do ano|próximo ano|sem pressa|vai depender|sem data/)) score += 5;

// 2. ORÇAMENTO (máx 35 pontos)
if (fullText.match(/\\d{4,5}.*reais|tenho.*orçamento|limite.*[0-9]/)) score += 35;
else if (fullText.match(/em torno de|aprox|algo como|na faixa/)) score += 25;
else if (fullText.match(/tenho recursos|tenho grana|consigo financiar/)) score += 15;
else if (fullText.match(/depende|conforme|vou ver|depois combino|sem ideia/)) score += 5;

// 3. PROJETO (máx 15 pontos)
if (fullText.match(/reforma|construindo|obra|em andamento|já começou/)) score += 15;
else if (fullText.match(/pro home office|meu quarto|sala de estar|cozinha|varanda/)) score += 10;
else if (fullText.match(/quero renovar|tá velho|mudar|desejo|ideia/)) score += 5;

// 4. COMPORTAMENTO (máx 15 pontos)
if (fullText.match(/quanto custa|preço|valor|agendar|marcar|quando você tem/)) score += 15;
else if (fullText.match(/qual é o material|que cores|qual tamanho|frete|instalação/)) score += 10;
else if (fullText.match(/ok|tá bom|blz|sim|não|achei legal/)) score += 5;

// 5. EXPERIÊNCIA (máx 5 pontos)
if (fullText.match(/já vi|conheco|comprei|frequento|indicação|meu amigo/)) score += 5;

// Classificação
let classification = '';
let shouldNotify = false;
let emoji = '';

if (score >= 90) {
  classification = 'QUENTE';
  emoji = '🔥';
  shouldNotify = true;
} else if (score >= 60) {
  classification = 'MORNO';
  emoji = '🟠';
} else if (score >= 30) {
  classification = 'FRIO';
  emoji = '🟡';
} else {
  classification = 'MUITO_FRIO';
  emoji = '❄️';
}

return {
  score,
  classification,
  emoji,
  shouldNotify
};

